  "fatima": {"fr": "Dérivé de l’arabe فطم (faṭama), « s’abstenir, sevrer ».", "en": "Derived from Arabic فطم (faṭama) meaning \"to abstain, to wean\".", "url": "https://www.behindthename.com/name/fatima", "refs": ["Ahmed, Salahuddin. A Dictionary of Muslim Names. New York University, 1999, page 255.", "Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 843."]},
  "fatin": {"fr": "« Charmante, séduisante, fascinante » en arabe.", "en": "Means \"charming, seductive, fascinating\" in Arabic.", "url": "https://www.behindthename.com/name/fatin-1"},
  "fawzi": {"fr": "« Triomphe, victoire » en arabe, dérivé de فاز (fāza), « triompher ».", "en": "Means \"triumph, victory\" in Arabic, a derivative of فاز (fāza) meaning \"to triumph\".", "url": "https://www.behindthename.com/name/fawzi", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 857."]},
  "fethi": {"fr": "Forme turque de Fathi, et aussi autre transcription du nom arabe, surtout employée en Afrique du Nord.", "en": "Turkish form of Fathi, as well as an alternate transcription of the Arabic name chiefly used in North Africa.", "url": "https://www.behindthename.com/name/fethi"},
  "firas": {"fr": "De l’arabe فراسة (firāsa), « perspicacité, finesse ».", "en": "From Arabic فراسة (firāsa) meaning \"acumen, keenness\".", "url": "https://www.behindthename.com/name/firas", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 825."]},
  "ghada": {"fr": "« Femme gracieuse » en arabe.", "en": "Means \"graceful woman\" in Arabic.", "url": "https://www.behindthename.com/name/ghada"},
