  "habiba": {"fr": "Féminin de Habib, qui signifie « bien-aimé, chéri » en arabe.", "en": "Feminine form of Habib. Means \"beloved, darling\" in Arabic.", "url": "https://www.behindthename.com/name/habib"},
  "habibullah": {"fr": "« Ami d’Allah », de l’arabe حبيب (ḥabīb), « ami », joint à الله (Allah).", "en": "Means \"friend of Allah\", from Arabic حبيب (ḥabīb) meaning \"friend\" combined with الله (Allah).", "url": "https://www.behindthename.com/name/habibullah", "refs": ["Ahmed, Salahuddin. A Dictionary of Muslim Names. New York University, 1999, page 62.", "Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 179."]},
  "hadeel": {"fr": "« Roucoulement (d’une colombe) » en arabe.", "en": "Means \"cooing (of a pigeon)\" in Arabic.", "url": "https://www.behindthename.com/name/hadil"},
