  "hakim": {"fr": "« Sage » en arabe, de la racine حكم (ḥakama), « juger, décider ».", "en": "Means \"wise\" in Arabic, from the root حكم (ḥakama) meaning \"to pass judgement, to decide\".", "url": "https://www.behindthename.com/name/hakim", "refs": ["Ahmed, Salahuddin. A Dictionary of Muslim Names. New York University, 1999, page 65.", "Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 228."]},
  "hakima": {"fr": "Féminin de Hakim, qui signifie « sage » en arabe, de la racine حكم (ḥakama), « juger, décider ».", "en": "Feminine form of Hakim. Means \"wise\" in Arabic, from the root حكم (ḥakama) meaning \"to pass judgement, to decide\".", "url": "https://www.behindthename.com/name/hakim", "refs": ["Ahmed, Salahuddin. A Dictionary of Muslim Names. New York University, 1999, page 65.", "Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 228."]},
  "hala": {"fr": "« Halo autour de la lune » en arabe.", "en": "Means \"halo around the moon\" in Arabic.", "url": "https://www.behindthename.com/name/hala"},
