  "hamid": {"fr": "« Celui qui loue » en arabe.", "en": "Means \"praiser\" in Arabic.", "url": "https://www.behindthename.com/name/hamid-2", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 238."]},
  "hamida": {"fr": "Féminin de Hamid, qui signifie « digne d’éloges » en arabe, de la racine حمد (ḥamida), « louer ».", "en": "Feminine form of Hamid 1. Means \"praiseworthy\" in Arabic, from the root حمد (ḥamida) meaning \"to praise\".", "url": "https://www.behindthename.com/name/hamid-1", "refs": ["Ahmed, Salahuddin. A Dictionary of Muslim Names. New York University, 1999, page 66.", "Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 238."]},
  "hamza": {"fr": "« Lion » en arabe, dérivé de حمز (ḥamuza), « fort, robuste ».", "en": "Means \"lion\" in Arabic, a derivative of حمز (ḥamuza) meaning \"strong, sturdy\".", "url": "https://www.behindthename.com/name/hamza"},
  "hana": {"fr": "« Félicité, bonheur » en arabe, de la racine هنأ (hanaʾa), « réjouir, jouir ».", "en": "Means \"bliss, happiness\" in Arabic, from the root هنأ (hanaʾa) meaning \"to gladden, to enjoy\".", "url": "https://www.behindthename.com/name/hana-1", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 1214."]},
