  "hasan": {"fr": "« Beau » en arabe, de la racine حسن (ḥasuna), « être beau, être bon ».", "en": "Means \"handsome\" in Arabic, from the root حسن (ḥasuna) meaning \"to be beautiful, to be good\".", "url": "https://www.behindthename.com/name/hasan", "refs": ["Ahmed, Salahuddin. A Dictionary of Muslim Names. New York University, 1999, page 68.", "Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 208."]},
  "hashim": {"fr": "« Celui qui broie, qui brise » en arabe, dérivé de la racine هشم (hashama), « broyer, détruire ».", "en": "Means \"crusher, breaker\" in Arabic, derived from the root هشم (hashama) meaning \"to crush, to destroy\".", "url": "https://www.behindthename.com/name/hashim", "refs": ["Ahmed, Salahuddin. A Dictionary of Muslim Names. New York University, 1999, page 62.", "Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 1206."]},
  "hasna": {"fr": "« Beauté » en arabe, dérivé de حسن (ḥasuna), « être beau, être bon ».", "en": "Means \"beauty\" in Arabic, a derivative of حسن (ḥasuna) meaning \"to be beautiful, to be good\".", "url": "https://www.behindthename.com/name/hasna", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 208."]},
  "hatim": {"fr": "« Déterminé, décidé » en arabe, dérivé de حتم (ḥatama), « décréter, décider ».", "en": "Means \"determined, decisive\" in Arabic, derived from حتم (ḥatama) meaning \"to decree, to decide\".", "url": "https://www.behindthename.com/name/hatim", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 183."]},
  "hayat": {"fr": "« Vie » en arabe, de حيي (ḥayiya), « vivre ».", "en": "Means \"life\" in Arabic, from حيي (ḥayiya) meaning \"to live\".", "url": "https://www.behindthename.com/name/hayat", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 256."]},
  "haytham": {"fr": "« Jeune aigle » en arabe.", "en": "Means \"young eagle\" in Arabic.", "url": "https://www.behindthename.com/name/haytham"},
