  "housni": {"fr": "Dérivé de l’arabe حسْن (ḥusn), « beauté, excellence, bonté ».", "en": "Derived from Arabic حسْن (ḥusn) meaning \"beauty, excellence, goodness\".", "url": "https://www.behindthename.com/name/husni", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 208."]},
  "huda": {"fr": "« Bonne direction » en arabe, de la racine هدى (hadā), « conduire sur le droit chemin, guider ».", "en": "Means \"right guidance\" in Arabic, from the root هدى (hadā) meaning \"to lead the right way, to guide\".", "url": "https://www.behindthename.com/name/huda", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 1199."]},
  "huriya": {"fr": "« Nymphe, vierge céleste » en arabe, en référence aux houris, belles jeunes femmes de l’au-delà selon l’islam.", "en": "Means \"nymph, heavenly maiden\" in Arabic, referring to the houris, who are beautiful maidens who dwell in the Islamic afterlife.", "url": "https://www.behindthename.com/name/huriya"},
  "husam": {"fr": "« Épée » en arabe, dérivé du verbe حسم (ḥasama), « trancher, achever, décider ».", "en": "Means \"sword\" in Arabic, a derivative of the verb حسم (ḥasama) meaning \"to sever, to finish, to decide\".", "url": "https://www.behindthename.com/name/husam", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 207."]},
  "husayn": {"fr": "Diminutif de Hasan, qui signifie « beau » en arabe, de la racine حسن (ḥasuna), « être beau, être bon ».", "en": "Diminutive of Hasan. Means \"handsome\" in Arabic, from the root حسن (ḥasuna) meaning \"to be beautiful, to be good\".", "url": "https://www.behindthename.com/name/hasan", "refs": ["Ahmed, Salahuddin. A Dictionary of Muslim Names. New York University, 1999, page 68.", "Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 208."]},
  "ibrahim": {"fr": "Forme arabe d’Abraham, également employée dans plusieurs autres langues.", "en": "Arabic form of Abraham, also used in several other languages.", "url": "https://www.behindthename.com/name/ibrahim"},
  "ibtisam": {"fr": "« Un sourire » en arabe, de la racine بسم (basama), « sourire ».", "en": "Means \"a smile\" in Arabic, from the root بسم (basama) meaning \"to smile\".", "url": "https://www.behindthename.com/name/ibtisam", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 73."]},
  "idris": {"fr": "Signifie peut-être « interprète, enseignant » en arabe, en lien avec la racine درس (darasa), « étudier, apprendre ».", "en": "Possibly means \"interpreter, teacher\" in Arabic, related to the root درس (darasa) meaning \"to study, to learn\".", "url": "https://www.behindthename.com/name/idris-1", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 321.", "Ahmed, Salahuddin. A Dictionary of Muslim Names. New York University, 1999, page 77."]},
  "ihsan": {"fr": "« Bienfaisance, bonne action » en arabe, de la racine حسن (ḥasuna), « être bon ».", "en": "Means \"charity, good deed\" in Arabic, from the root حسن (ḥasuna) meaning \"to be good\".", "url": "https://www.behindthename.com/name/ihsan", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 208."]},
  "ikram": {"fr": "« Honneur » en arabe, de la racine كرم (karuma), « être généreux ».", "en": "Means \"honour\" in Arabic, from the root كرم (karuma) meaning \"to be generous\".", "url": "https://www.behindthename.com/name/ikram", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 962."]},
  "ilham": {"fr": "« Inspiration » en arabe.", "en": "Means \"inspiration\" in Arabic.", "url": "https://www.behindthename.com/name/ilham"},
  "ilyas": {"fr": "Forme arabe d’Élie, également employée dans plusieurs autres langues.", "en": "Arabic form of Elijah, also used in several other languages.", "url": "https://www.behindthename.com/name/ilyas"},
  "imad": {"fr": "« Soutien, pilier » en arabe, dérivé de عمد (ʿamada), « soutenir ».", "en": "Means \"support, pillar\" in Arabic, a derivative of عمد (ʿamada) meaning \"to support\".", "url": "https://www.behindthename.com/name/imad", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 751."]},
  "iman": {"fr": "« Foi » en arabe, dérivé de أمن (ʾamuna), « être fidèle ».", "en": "Means \"faith\" in Arabic, derived from أمن (ʾamuna) meaning \"to be faithful\".", "url": "https://www.behindthename.com/name/iman", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 35."]},
  "imran": {"fr": "Forme arabe d’Amram, le père de Moïse.", "en": "Arabic form of Amram, referring to the father of Moses.", "url": "https://www.behindthename.com/name/imran"},
