  "ishaq": {"fr": "Forme arabe d’Isaac.", "en": "Arabic form of Isaac.", "url": "https://www.behindthename.com/name/ishaq"},
  "ismail": {"fr": "Forme arabe d’Ismaël, également employée dans plusieurs autres langues.", "en": "Arabic form of Ishmael, also used in several other languages.", "url": "https://www.behindthename.com/name/ismail"},
  "isra": {"fr": "« Voyage nocturne » en arabe, dérivé de سرى (sarā), « voyager de nuit ».", "en": "Means \"nocturnal journey\" in Arabic, derived from سرى (sarā) meaning \"to travel by night\".", "url": "https://www.behindthename.com/name/isra", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 476."]},
  "iyad": {"fr": "« Force, soutien » en arabe, de la racine أيّد (ʾayyada), « soutenir ».", "en": "Means \"strength, support\" in Arabic, from the root أيّد (ʾayyada) meaning \"to support\".", "url": "https://www.behindthename.com/name/iyad", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 47."]},
