  "jannah": {"fr": "« Paradis, jardin » en arabe.", "en": "Means \"paradise, garden\" in Arabic.", "url": "https://www.behindthename.com/name/janna-2", "refs": ["Ahmed, Salahuddin. A Dictionary of Muslim Names. New York University, 1999, page 273.", "Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 164."]},
  "jawad": {"fr": "« Généreux » en arabe, dérivé de جاد (jāda), « être excellent, être généreux ».", "en": "Means \"generous\" in Arabic, a derivative of جاد (jāda) meaning \"to be excellent, to be generous\".", "url": "https://www.behindthename.com/name/jawad", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 172."]},
