  "karim": {"fr": "« Généreux, noble » en arabe, de la racine كرم (karuma), « être généreux ».", "en": "Means \"generous, noble\" in Arabic, from the root كرم (karuma) meaning \"to be generous\".", "url": "https://www.behindthename.com/name/karim", "refs": ["Ahmed, Salahuddin. A Dictionary of Muslim Names. New York University, 1999, page 95.", "Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 962."]},
  "karima": {"fr": "Féminin de Karim, qui signifie « généreux, noble » en arabe, de la racine كرم (karuma), « être généreux ».", "en": "Feminine form of Karim. Means \"generous, noble\" in Arabic, from the root كرم (karuma) meaning \"to be generous\".", "url": "https://www.behindthename.com/name/karim", "refs": ["Ahmed, Salahuddin. A Dictionary of Muslim Names. New York University, 1999, page 95.", "Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 962."]},
