  "khayra": {"fr": "« Bonne action » en arabe, dérivé de خير (khayr), « bien, charité ».", "en": "Means \"good deed\" in Arabic, a derivative of خير (khayr) meaning \"goodness, charity\".", "url": "https://www.behindthename.com/name/khayra", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 308."]},
  "lakhdar": {"fr": "Dérivé de l’arabe الأخضر (al-ʾAkhḍar), « le vert ».", "en": "Derived from Arabic الأخضر (al-ʾAkhḍar) meaning \"the green\".", "url": "https://www.behindthename.com/name/lakhdar"},
  "lamia": {"fr": "« Brillante, rayonnante » en arabe, dérivé de la racine لمع (lamaʿa), « briller, scintiller ».", "en": "Means \"shining, radiant\" in Arabic, derived from the root لمع (lamaʿa) meaning \"to shine, to gleam\".", "url": "https://www.behindthename.com/name/lamia-1", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 1031."]},
  "latif": {"fr": "« Doux, bienveillant » en arabe.", "en": "Means \"gentle, kind\" in Arabic.", "url": "https://www.behindthename.com/name/latif", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 1018."]},
