  "lina": {"fr": "« Douce, tendre » en arabe, dérivé de لان (lāna), « être doux ».", "en": "Means \"soft, tender\" in Arabic, derived from لان (lāna) meaning \"to be soft\".", "url": "https://www.behindthename.com/name/lina-1", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 1041."]},
  "luay": {"fr": "« Petit bœuf sauvage » en arabe, diminutif de لأًى (laʾan), « bœuf sauvage » (au figuré « bouclier, protecteur »).", "en": "Means \"little wild ox\" in Arabic, a diminutive of لأًى (laʾan) \"wild ox\" (figuratively meaning \"shield, protector\").", "url": "https://www.behindthename.com/name/luay"},
