  "luqman": {"fr": "Sens inconnu.", "en": "Meaning unknown.", "url": "https://www.behindthename.com/name/luqman"},
  "lutfi": {"fr": "« Bienveillant, doux » en arabe, dérivé de لطف (laṭafa), « être bienveillant ».", "en": "Means \"kind, gentle\" in Arabic, a derivative of لطف (laṭafa) meaning \"to be kind\".", "url": "https://www.behindthename.com/name/lutfi", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 1018."]},
  "maha": {"fr": "« Oryx » en arabe.", "en": "Means \"oryx\" in Arabic.", "url": "https://www.behindthename.com/name/maha"},
