  "mamun": {"fr": "« Digne de confiance » en arabe, dérivé de أمن (ʾamuna), « être fidèle ».", "en": "Means \"trustworthy\" in Arabic, derived from أمن (ʾamuna) meaning \"to be faithful\".", "url": "https://www.behindthename.com/name/mamun", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 35."]},
  "manal": {"fr": "« Réussite, obtention » en arabe, de la racine نال (nāla), « obtenir, atteindre ».", "en": "Means \"achievement, attainment\" in Arabic, from the root نال (nāla) meaning \"to get, to reach\".", "url": "https://www.behindthename.com/name/manal", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 1186."]},
  "mansur": {"fr": "« Victorieux, soutenu » en arabe, dérivé de نصر (naṣara), « aider, secourir ».", "en": "Means \"victorious, supported\" in Arabic, a derivative of نصر (naṣara) meaning \"to help, to aid\".", "url": "https://www.behindthename.com/name/mansur", "refs": ["Ahmed, Salahuddin. A Dictionary of Muslim Names. New York University, 1999, page 113.", "Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 1138."]},
