  "marwa": {"fr": "De l’arabe مرو (marw), « cailloux, silex » ; c’est aussi le nom d’une plante odorante (Maerua crassifolia).", "en": "From Arabic مرو (marw) meaning \"pebbles, flint\", also the name of a type of fragrant plant (species Maerua crassifolia).", "url": "https://www.behindthename.com/name/marwa", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 1062."]},
  "marwan": {"fr": "Masculin de Marwa, de l’arabe مرو (marw), « cailloux, silex » ; c’est aussi le nom d’une plante odorante (Maerua crassifolia).", "en": "Masculine form of Marwa. From Arabic مرو (marw) meaning \"pebbles, flint\", also the name of a type of fragrant plant (species Maerua crassifolia).", "url": "https://www.behindthename.com/name/marwa", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 1062."]},
  "maryam": {"fr": "Forme arabe de Miryam, présente dans le Coran.", "en": "Arabic form of Miryam appearing in the Quran.", "url": "https://www.behindthename.com/name/maryam"},
  "masud": {"fr": "« Chanceux, fortuné, heureux » en arabe, dérivé de la racine سعد (saʿida), « être heureux, avoir de la chance ».", "en": "Means \"lucky, fortunate, happy\" in Arabic, derived from the root سعد (saʿida) meaning \"to be happy, to be lucky\".", "url": "https://www.behindthename.com/name/masud", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 478."]},
