  "maysa": {"fr": "Dérivé de l’arabe ميس (mays), « allure fière, démarche fière ».", "en": "Derived from Arabic ميس (mays) meaning \"proud bearing, walking with a proud gait\".", "url": "https://www.behindthename.com/name/maysa", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 1097."]},
  "mazin": {"fr": "« Nuages de pluie » en arabe.", "en": "Means \"rain clouds\" in Arabic.", "url": "https://www.behindthename.com/name/mazin"},
