  "mokhtar": {"fr": "Forme nord-africaine, persane et malaise de Mukhtar.", "en": "North African, Persian and Malay form of Mukhtar.", "url": "https://www.behindthename.com/name/mokhtar"},
  "mouloud": {"fr": "« Nouveau-né » en arabe, dérivé de ولد (walada), « enfanter » ; désigne aussi l’anniversaire de naissance du Prophète Muhammad.", "en": "Means \"newborn\" in Arabic, a derivative of ولد (walada) meaning \"to give birth\", used to refer to the birthday of the Prophet Muhammad.", "url": "https://www.behindthename.com/name/mawlud", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 1285."]},
  "mourad": {"fr": "« Souhait, désir, voulu » en arabe.", "en": "Means \"wish, desire, wanted\" in Arabic.", "url": "https://www.behindthename.com/name/murad"},
  "mubina": {"fr": "Féminin de Mubin, qui signifie « clair, distinct » en arabe, dérivé de بان (bāna), « être manifeste, être évident ».", "en": "Feminine form of Mubin. Means \"clear, distinct\" in Arabic, a derivative of بان (bāna) meaning \"to be plain, to be evident\".", "url": "https://www.behindthename.com/name/mubin", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 105."]},
  "muhammad": {"fr": "« Loué, digne d’éloges » en arabe, de la racine حمد (ḥamida), « louer ».", "en": "Means \"praised, commendable\" in Arabic, derived from the root حمد (ḥamida) meaning \"to praise\".", "url": "https://www.behindthename.com/name/muhammad", "refs": ["Ahmed, Salahuddin. A Dictionary of Muslim Names. New York University, 1999, page 125.", "Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 238."]},
  "muhsina": {"fr": "Féminin de Muhsin, qui signifie « bienfaisant, charitable » en arabe, dérivé de حسن (ḥasuna), « être bon, être beau ».", "en": "Feminine form of Muhsin. Means \"beneficent, charitable\" in Arabic, a derivative of حسن (ḥasuna) meaning \"to be good, to be beautiful\".", "url": "https://www.behindthename.com/name/muhsin", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 208."]},
  "muna": {"fr": "« Souhaits, désirs », du pluriel de Munya.", "en": "Means \"wishes, desires\", from the plural form of Munya.", "url": "https://www.behindthename.com/name/muna"},
  "munir": {"fr": "« Brillant, lumineux » en arabe, en lien avec la racine نوّر (nawwara), « illuminer, éclairer ».", "en": "Means \"bright, shining\" in Arabic, related to the root نوّر (nawwara) meaning \"to illuminate, to light\".", "url": "https://www.behindthename.com/name/munir", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 1182."]},
  "munira": {"fr": "Féminin de Munir, qui signifie « brillant, lumineux » en arabe, en lien avec la racine نوّر (nawwara), « illuminer, éclairer ».", "en": "Feminine form of Munir. Means \"bright, shining\" in Arabic, related to the root نوّر (nawwara) meaning \"to illuminate, to light\".", "url": "https://www.behindthename.com/name/munir", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 1182."]},
  "murtada": {"fr": "« Choisi » en arabe.", "en": "Means \"chosen\" in Arabic.", "url": "https://www.behindthename.com/name/murtada"},
