  "mustafa": {"fr": "« Choisi » en arabe, dérivé de اصطفا (iṣṭafā), « choisir ».", "en": "Means \"chosen\" in Arabic, derived from اصطفا (iṣṭafā) meaning \"to choose\".", "url": "https://www.behindthename.com/name/mustafa", "refs": ["Ahmed, Salahuddin. A Dictionary of Muslim Names. New York University, 1999, page 138.", "Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 606."]},
  "nabil": {"fr": "« Noble » en arabe.", "en": "Means \"noble\" in Arabic.", "url": "https://www.behindthename.com/name/nabil"},
