  "nada": {"fr": "De l’arabe نَدًى (nadan), « rosée, humidité, générosité », dérivé de ندي (nadiya), « être humide ».", "en": "From Arabic نَدًى (nadan) meaning \"dew, moisture, generosity\", a derivative of ندي (nadiya) meaning \"to be moist, to be damp\".", "url": "https://www.behindthename.com/name/nada-1", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 1117."]},
  "nadia": {"fr": "« Annonce, appel » en arabe, dérivé de نادى (nādā), « appeler, annoncer, inviter ».", "en": "Means \"announcement, call\" in Arabic, derived from نادى (nādā) meaning \"to call, to announce, to invite\".", "url": "https://www.behindthename.com/name/nadiyya", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 1118."]},
  "nadim": {"fr": "« Compagnon de boisson » en arabe, dérivé de ندم (nadima), « boire ensemble ».", "en": "Means \"drinking companion\" in Arabic, derived from ندم (nadima) meaning \"to drink together\".", "url": "https://www.behindthename.com/name/nadim", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 117."]},
