  "nael": {"fr": "« Celui qui obtient » en arabe.", "en": "Means \"attainer\" in Arabic.", "url": "https://www.behindthename.com/name/nail", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 1189."]},
  "naim": {"fr": "« Paisible, heureux, à l’aise » en arabe, dérivé de la racine نعم (naʿima), « vivre dans l’aisance, être ravi ».", "en": "Means \"tranquil, happy, at ease\" in Arabic, derived from the root نعم (naʿima) meaning \"to live in comfort, to be delighted\".", "url": "https://www.behindthename.com/name/naim", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 1149."]},
  "naima": {"fr": "Féminin de Naim, qui signifie « paisible, heureux, à l’aise » en arabe, dérivé de la racine نعم (naʿima), « vivre dans l’aisance, être ravi ».", "en": "Feminine form of Naim. Means \"tranquil, happy, at ease\" in Arabic, derived from the root نعم (naʿima) meaning \"to live in comfort, to be delighted\".", "url": "https://www.behindthename.com/name/naim", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 1149."]},
  "najah": {"fr": "« Succès » en arabe.", "en": "Means \"success\" in Arabic.", "url": "https://www.behindthename.com/name/najah"},
  "najat": {"fr": "« Salut, sauvetage, délivrance » en arabe, de la racine نجا (najā), « sauver ».", "en": "Means \"salvation, rescue, deliverance\" in Arabic, from the root نجا (najā) meaning \"to save\".", "url": "https://www.behindthename.com/name/najat", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 1110."]},
  "naji": {"fr": "« Ami intime » en arabe, dérivé de نجا (najā), « sauver, confier ».", "en": "Means \"intimate friend\" in Arabic, a derivative of نجا (najā) meaning \"to save, to entrust, to confide in\".", "url": "https://www.behindthename.com/name/naji", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 1110."]},
  "najib": {"fr": "« Noble, distingué » en arabe.", "en": "Means \"noble, distinguished\" in Arabic.", "url": "https://www.behindthename.com/name/najib", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 1107."]},
  "najla": {"fr": "« Aux grands yeux » en arabe.", "en": "Means \"wide-eyed\" in Arabic.", "url": "https://www.behindthename.com/name/najla"},
  "najma": {"fr": "Féminin de Najm, qui signifie « étoile » en arabe.", "en": "Feminine form of Najm. Means \"star\" in Arabic.", "url": "https://www.behindthename.com/name/najm"},
  "najwa": {"fr": "« Secret, murmure, conversation confidentielle » en arabe, de la racine نجا (najā), « sauver, confier ».", "en": "Means \"secret, whisper, confidential talk\" in Arabic, from the root نجا (najā) meaning \"to save, to entrust, to confide in\".", "url": "https://www.behindthename.com/name/najwa", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 1110."]},
  "nasir": {"fr": "« Celui qui aide » en arabe, de la racine نصر (naṣara), « aider, secourir ».", "en": "Means \"helper\" in Arabic, from the root نصر (naṣara) meaning \"to help, to aid\".", "url": "https://www.behindthename.com/name/nasir", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 1138."]},
  "nassim": {"fr": "« Brise » en arabe.", "en": "Means \"breeze\" in Arabic.", "url": "https://www.behindthename.com/name/nasim"},
