  "nur": {"fr": "« Lumière » en arabe.", "en": "Means \"light\" in Arabic.", "url": "https://www.behindthename.com/name/nur", "refs": ["Ahmed, Salahuddin. A Dictionary of Muslim Names. New York University, 1999, page 303.", "Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 1182."]},
  "nusaybah": {"fr": "Diminutif de Nasiba, féminin de Nasib.", "en": "Diminutive of Nasiba 2. Feminine form of Nasib.", "url": "https://www.behindthename.com/name/nusayba"},
  "qamar": {"fr": "« Lune » en arabe.", "en": "Means \"moon\" in Arabic.", "url": "https://www.behindthename.com/name/qamar"},
  "qasim": {"fr": "« Celui qui partage les biens entre les gens » en arabe, dérivé de قسم (qasama), « diviser, distribuer ».", "en": "Means \"one who divides goods among people\" in Arabic, derived from قسم (qasama) meaning \"to divide, to distribute\".", "url": "https://www.behindthename.com/name/qasim", "refs": ["Ahmed, Salahuddin. A Dictionary of Muslim Names. New York University, 1999, page 161.", "Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 893."]},
  "qays": {"fr": "« Mesure » en arabe.", "en": "Means \"measurement\" in Arabic.", "url": "https://www.behindthename.com/name/qays"},
  "rabab": {"fr": "D’un mot arabe désignant un instrument de musique à cordes.", "en": "From an Arabic word referring to a type of stringed musical instrument.", "url": "https://www.behindthename.com/name/rubab"},
  "rabeh": {"fr": "« Gagnant » en arabe, de la racine ربح (rabiḥa), « gagner, tirer profit ».", "en": "Means \"winner, gainer\" in Arabic, from the root ربح (rabiḥa) meaning \"to win, to profit\".", "url": "https://www.behindthename.com/name/rabih-1", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 371."]},
  "rabia": {"fr": "« Quatrième » en arabe, dérivé de أربعة (ʾarbaʿa), « quatre ».", "en": "Means \"fourth\" in Arabic, a derivative of أربعة (ʾarbaʿa) meaning \"four\".", "url": "https://www.behindthename.com/name/raabi02a", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 374."]},
  "rachida": {"fr": "Féminin de Rashid, qui signifie « bien guidé » en arabe.", "en": "Feminine form of Rashid. Means \"rightly guided\" in Arabic.", "url": "https://www.behindthename.com/name/rashida"},
  "rafiq": {"fr": "« Ami » ou « doux, bienveillant » en arabe.", "en": "Means either \"friend\" or \"gentle, kind\" in Arabic.", "url": "https://www.behindthename.com/name/rafiq"},
  "rahaf": {"fr": "« Délicate, fine, mince » en arabe.", "en": "Means \"delicate, fine, thin\" in Arabic.", "url": "https://www.behindthename.com/name/rahaf"},
  "rahma": {"fr": "« Miséricorde, compassion » en arabe.", "en": "Means \"mercy, compassion\" in Arabic.", "url": "https://www.behindthename.com/name/rahma"},
  "raja": {"fr": "« Espoir » en arabe, de la racine رجا (rajā), « espérer, s’attendre à ».", "en": "Means \"hope\" in Arabic, from the root رجا (rajā) meaning \"to hope, to anticipate\".", "url": "https://www.behindthename.com/name/raja-1", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 381."]},
  "rajab": {"fr": "Du nom du septième mois du calendrier islamique, dérivé de l’arabe رجب (rajaba), « respect, crainte révérencielle ».", "en": "From the name of the seventh month in the Islamic calendar, derived from Arabic رجب (rajaba) meaning \"respect, awe\".", "url": "https://www.behindthename.com/name/rajab", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 377."]},
  "rami": {"fr": "« Archer, tireur » en arabe.", "en": "Means \"archer, marksman\" in Arabic.", "url": "https://www.behindthename.com/name/rami"},
