  "rana": {"fr": "« Regarder fixement, contempler » en arabe.", "en": "Means \"to gaze, to look intently\" in Arabic.", "url": "https://www.behindthename.com/name/rana-1"},
  "raouf": {"fr": "« Compatissant » en arabe.", "en": "Means \"compassionate\" in Arabic.", "url": "https://www.behindthename.com/name/rauf"},
  "rasha": {"fr": "« Jeune gazelle » en arabe.", "en": "Means \"young gazelle\" in Arabic.", "url": "https://www.behindthename.com/name/rasha"},
  "rashad": {"fr": "« Bon sens, bonne direction » en arabe, de la racine رشد (rashada), « être sur le droit chemin ».", "en": "Means \"good sense, good guidance\" in Arabic, from the root رشد (rashada) meaning \"to be on the right path\".", "url": "https://www.behindthename.com/name/rashad", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 395."]},
  "rashid": {"fr": "« Bien guidé » en arabe.", "en": "Means \"rightly guided\" in Arabic.", "url": "https://www.behindthename.com/name/rashid", "refs": ["Ahmed, Salahuddin. A Dictionary of Muslim Names. New York University, 1999, page 170.", "Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 395."]},
  "rawda": {"fr": "« Prairie, jardin » en arabe.", "en": "Means \"meadow, garden\" in Arabic.", "url": "https://www.behindthename.com/name/rawda"},
