  "shaima": {"fr": "Signifie peut-être « grains de beauté » en arabe.", "en": "Possibly means \"beauty marks\" in Arabic.", "url": "https://www.behindthename.com/name/shaima"},
  "shakir": {"fr": "« Reconnaissant » en arabe, de la racine شكر (shakara), « remercier ».", "en": "Means \"thankful\" in Arabic, from the root شكر (shakara) meaning \"to thank\".", "url": "https://www.behindthename.com/name/shakir", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 563."]},
  "shams": {"fr": "« Soleil » en arabe.", "en": "Means \"sun\" in Arabic.", "url": "https://www.behindthename.com/name/shams"},
  "sharif": {"fr": "« Noble, éminent » en arabe, dérivé de شرف (sharufa), « être noble, être illustre ».", "en": "Means \"noble, eminent\" in Arabic, a derivative of شرف (sharufa) meaning \"to be noble, to be illustrious\".", "url": "https://www.behindthename.com/name/sharif", "refs": ["Ahmed, Salahuddin. A Dictionary of Muslim Names. New York University, 1999, page 199.", "Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 545."]},
  "shuayb": {"fr": "Diminutif de l’arabe شعب (shuʿab), « branche, domaine d’étude ».", "en": "Diminutive of Arabic شعب (shuʿab) meaning \"branch, field of study\".", "url": "https://www.behindthename.com/name/shuayb", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 552."]},
  "siham": {"fr": "« Flèches » en arabe, pluriel de سهم (sahm).", "en": "Means \"arrows\" in Arabic, the plural of سهم (sahm).", "url": "https://www.behindthename.com/name/siham", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 511."]},
  "sofiane": {"fr": "« Agile, rapide, léger » en arabe.", "en": "Means \"nimble, fast, light\" in Arabic.", "url": "https://www.behindthename.com/name/sufyan"},
  "souad": {"fr": "« Bonheur, chance » en arabe, de la racine سعد (saʿida), « être heureux, avoir de la chance ».", "en": "Means \"happiness, luck\" in Arabic, from the root سعد (saʿida) meaning \"to be happy, to be lucky\".", "url": "https://www.behindthename.com/name/suad", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 478."]},
  "suhaila": {"fr": "Féminin de Suhail, dérivé de l’arabe سهل (sahl), « plat, uni, lisse ».", "en": "Feminine form of Suhail. Derived from Arabic سهل (sahl) meaning \"level, even, smooth\".", "url": "https://www.behindthename.com/name/suhail", "refs": ["Wehr, Hans. A Dictionary of Modern Written Arabic. Spoken Language Services, 1979, page 510."]},
